const body = $json.body ?? $json;
const message = typeof body.message === 'string' ? body.message.trim() : '';
if (!message) {
  throw new Error('message is required');
}
const service = typeof body.service === 'string' ? body.service.trim() : '';
const location = typeof body.location === 'string' ? body.location.trim() : '';
const propertyType = typeof body.propertyType === 'string' ? body.propertyType.trim() : '';
const workType = typeof body.workType === 'string' ? body.workType.trim() : '';
const sessionId = typeof body.sessionId === 'string' && body.sessionId.trim() ? body.sessionId.trim() : `ps-chat-${Date.now()}`;
const contextLines = [
  service ? `Service: ${service}` : '',
  location ? `Location: ${location}, Pune` : '',
  propertyType ? `Property type: ${propertyType}` : '',
  workType ? `Work type: ${workType}` : '',
].filter(Boolean).join('\n');
return [{
  json: {
    message,
    service,
    location,
    propertyType,
    workType,
    sessionId,
    prompt: `You are PS Project / Presenti Services staffing assistant. Reply politely, briefly, and ask for missing details only when needed.\n\n${contextLines}\nCustomer message: ${message}`
  }
}];
